function validate([s]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 500000) return 's needs 3 to 5 * 10^5 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

