function maximumLength(s) {
  const runs = Array.from({ length: 26 }, () => []);
  let start = 0;
  for (let i = 1; i <= s.length; i++) {
    if (i === s.length || s[i] !== s[start]) {
      runs[s.charCodeAt(start) - 97].push(i - start);
      start = i;
    }
  }
  let best = -1;
  for (const lengths of runs) {
    let longest = 0;
    for (const length of lengths) {
      longest = Math.max(longest, length);
    }
    const count = new Array(longest + 1).fill(0);
    for (const length of lengths) {
      count[length]++;
    }
    let atLeast = 0;
    let occurrences = 0;
    for (let len = longest; len >= 1; len--) {
      atLeast += count[len];
      occurrences += atLeast;
      if (occurrences >= 3) {
        best = Math.max(best, len);
        break;
      }
    }
  }
  return best;
}

