function maximumLength(s) {
  // For each length from longest to shortest, count every special substring of that length directly.
  for (let len = s.length; len >= 1; len--) {
    const seen = new Map();
    for (let i = 0; i + len <= s.length; i++) {
      const piece = s.slice(i, i + len);
      if (piece === piece[0].repeat(len)) {
        const total = (seen.get(piece) || 0) + 1;
        if (total >= 3) return len;
        seen.set(piece, total);
      }
    }
  }
  return -1;
}

