function generate(rand, size) {
  const target = size === 'large' ? 10000 : 3 + Math.floor(rand() * 14);
  const shape = Math.floor(rand() * 4);
  const letters = shape === 0 ? 1 : shape === 1 ? 2 : shape === 2 ? 3 : 26;
  const maxRun = size === 'large' ? (shape === 3 ? 3 : 1 + Math.floor(rand() * 400)) : 1 + Math.floor(rand() * 6);
  let s = '';
  while (s.length < target) {
    const letter = String.fromCharCode(97 + Math.floor(rand() * letters));
    s += letter.repeat(1 + Math.floor(rand() * maxRun));
  }
  return [s.slice(0, target)];
}
